"""Normative architecture; SVG is reproducible using only the standard library."""
from pathlib import Path
from html import escape
A=['''<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="1590" viewBox="0 0 1800 1590" role="img" aria-labelledby="title desc"><title id="title">Svalbard normative transceiver architecture</title><desc id="desc">RF west, wired east, timing north, host south. Fifty terminals. RF and wired payload operation exclusive. External clock input is an alternate mode of REF_IN. Physical performance remains unqualified.</desc><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto-start-reverse"><path d="M0 0L8 4L0 8" fill="#355269"/></marker></defs><rect width="1800" height="1590" fill="white"/><g font-family="DejaVu Sans,sans-serif" fill="#172a3a">''']
def text(x,y,t,size=16,bold=False):
 A.append(f'<text x="{x}" y="{y}" font-size="{size}" font-weight="{600 if bold else 400}">{escape(t)}</text>')
def box(x,y,w,h,title,lines=(),fill='#f1f6fa'):
 A.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="5" fill="{fill}" stroke="#8096a6"/>')
 text(x+12,y+25,title,17,True)
 for i,l in enumerate(lines):text(x+12,y+49+i*21,l,14)
def wire(pts,clock=False,both=False):
 A.append('<polyline points="'+' '.join(f'{x},{y}' for x,y in pts)+'" fill="none" stroke="'+('#8655a2' if clock else '#355269')+'" stroke-width="2" '+('stroke-dasharray="6 4" ' if clock else '')+'marker-end="url(#a)" '+('marker-start="url(#a)"' if both else '')+'/>')
text(30,38,'SVALBARD / NORMATIVE ARCHITECTURE',28,True)
text(30,67,'Selected functional boundaries • circuit topology and physical performance remain to be qualified',17)
box(210,150,1380,970,'ONE GF180MCU DIE • RF OR WIRED PAYLOAD • 50 TOTAL TERMINALS',(), '#fcfdfe')
text(230,203,'Approximate placement neighborhoods; not to scale. 12.92 mm² core allocation includes 2.92 mm² reserve.',14)
box(590,85,610,65,'REF_IN (1)',('Alternate external reference / clock / RF LO; no simultaneous inputs',),'#fff6df')
wire([(1190,150),(1115,150),(1115,205),(1080,205),(1080,220)],True)
box(700,220,400,110,'Qualified input + stopped source selection',('Separate RF-capable conditioning branch required', 'Reference → autonomous loop OR clock/LO bypass', 'Input bandwidth, swing and additive noise: open'))
box(245,220,405,110,'RF synthesis + local quadrature',('PFD / charge pump / loop filter / tunable VCO', 'External LO bypass → I/Q phase generation', 'Local LO buffers; programmable sample divider'))
box(1150,220,405,110,'Wired TX synthesis + phase control',('PFD / charge pump / filter / oscillator / divider', 'External timing or synthesis; flexible ×10 mode', 'Independent RX CDR remains mandatory'))
wire([(700,266),(650,266)],True);wire([(1100,266),(1150,266)],True)
text(250,370,'RF RX • differential I/Q branches',20,True)
box(20,412,170,80,'RF_RX P/N (2)',('Board preselection', 'matching / balun'),'#fff6df')
box(245,400,180,95,'Input + LNA',('Protection / bias', 'Selectable gain'))
box(460,400,180,95,'I / Q mixers',('LO-I / LO-Q', 'Separate branches'))
box(675,400,200,95,'PGA + tunable LPF',('Offset / common-mode', 'Narrow & wide settings'))
box(910,400,180,95,'I / Q ADCs',('Sampling / quantization', 'Buffered references'))
for a,b in [(190,245),(425,460),(640,675),(875,910)]:wire([(a,455),(b,455)])
text(700,355,'LO-I / LO-Q → local RX and TX mixer ports',14)
wire([(550,385),(550,400)],True)
text(250,540,'RF TX • differential I/Q branches',20,True)
box(20,572,170,95,'RF_TX P/N (2)',('Board matching / filter', 'External PA as needed'),'#fff6df')
box(245,565,180,95,'RF output driver',('Gain / bias / headroom', 'Summed I/Q output'))
box(460,565,180,95,'I / Q upmixers',('LO-I / LO-Q', 'Local summation'))
box(675,565,200,95,'Reconstruction LPF',('Selectable cutoff / gain', 'Order not yet frozen'))
box(910,565,180,95,'I / Q DACs',('Registered update', 'Buffered references'))
for a,b in [(245,190),(460,425),(675,640),(910,875)]:wire([(a,615),(b,615)])
wire([(550,550),(550,565)],True)
box(1140,385,410,120,'Wired RX / shared USB pair',('Protection / switchable termination / common mode', 'Serial CTLE → slicers → phase sampler / RX CDR', 'Deserializer / alignment → RX words', 'USB HS + FS/LS receiver, squelch and line states'))
box(1610,405,175,100,'WIRE_RX P/N (2)',('USB D+ / D− alias', 'Bidirectional in USB'),'#fff6df')
wire([(1610,455),(1550,455)],both=True)
box(1140,550,410,130,'Wired TX / specialized pad branches',('TX words → serializer → main / postcursor driver', 'Serial idle / load detect; DC TMDS pad mode', 'USB HS + FS/LS drive / pulls → WIRE_RX pair', 'WIRE_TX high impedance during USB operation'))
box(1610,570,175,85,'WIRE_TX P/N (2)',('Serial / TMDS', 'Board termination'),'#fff6df')
wire([(1550,615),(1610,615)])
wire([(1515,550),(1570,550),(1570,485),(1550,485)])
wire([(1360,330),(1360,360),(1120,360),(1120,585),(1140,585)],True)
box(245,715,410,130,'Shared bias / converter reference services',('Startup → V/I reference → error amp + source/sink buffer', 'Local reservoirs, isolation and trim; replicas as needed', 'Share slow services where loading permits', 'No universal GHz analog crossbar'),'#fff8e9')
box(690,715,400,130,'Clock, configuration and observation',('LO dividers → ADC/DAC timing and RF D2H clock', 'Stop / select / settle / train / run; lock-loss recovery', 'SPI trims, bounded status and existing stream capture', 'Panel-local clock / bias / control fanout'),'#f7f0fa')
box(1610,745,175,85,'PWR / GND (14)',('7 supply / return pairs', 'Board regulation'),'#fff6df')
wire([(1610,790),(1550,790)])
box(1140,715,410,130,'Supply / return distribution',('CORE ×1, HOST ×2, WIRE ×2, RF ×1, PLL ×1 pairs', 'External regulation / decoupling / damping allowed', 'Local isolation and filtering; regulators not frozen', 'Host harmonics and package coupling remain risks'),'#fff8e9')
wire([(1000,495),(1105,495),(1105,885),(900,885),(900,910)])
wire([(870,910),(870,865),(1115,865),(1115,645),(1090,645)])
wire([(1200,505),(1128,505),(1128,880),(1250,880),(1250,910)])
wire([(1290,910),(1290,890),(1565,890),(1565,695),(1200,695),(1200,680)])
box(245,910,410,125,'SPI / reset / resource ownership',('Generic numeric controls; no chip protocol profiles', 'Atomic configuration; inactive payload isolated', 'Calibration, status, event scheduling and recovery', 'Bulk capture / waveform memory stays on FPGA'))
box(690,910,860,125,'Shared transport / short queues / GPIO PHY',('RF I/Q or wired words ↔ packing / gearbox ↔ bounded CDC / elasticity ↔ DDR capture / launch', 'No packet-sized storage promise; sustained pacing, underrun and reset epochs must close', 'D2H clock owned by active chip path; H2D clock supplied by FPGA', 'Wired line-rate sampling stays dedicated; RF converters are not serial-lane samplers'))
wire([(655,970),(690,970)],both=True)
box(245,1060,410,75,'SPI (4) + RESET_N (1)',('Independent configuration / recovery',),'#fff6df')
box(720,1060,370,75,'H2D[9:0] + H2D_CLK (11)',('FPGA → chip, source-synchronous DDR',),'#fff6df')
box(1150,1060,400,75,'D2H[9:0] + D2H_CLK (11)',('Chip → FPGA, source-synchronous DDR',),'#fff6df')
wire([(450,1060),(450,1035)]);wire([(900,1060),(900,1035)]);wire([(1350,1035),(1350,1060)])
box(245,1190,1305,145,'EXTERNAL FPGA + BOARD • explicitly outside the die budget',('FPGA: protocol controllers / PCS / modem / CRC / FEC; fractional-rate resampling and TX FIR interpolation; bulk storage.', 'RF rate candidate: LO ÷64/128/256/512 samples; LO ÷16 forwarded DDR clock. FPGA pays filter history and causal latency.', 'Recovery: actual protocol preambles / tracking; selectable filter settings trade clean-signal fidelity against blocker rejection.', 'Board: clean oscillator / LO, RF preselection / matching, optional PA, power / decoupling; specialized wired support as required.'),'#eaf3ff')
wire([(450,1190),(450,1135)],both=True);wire([(900,1190),(900,1135)]);wire([(1350,1135),(1350,1190)])
text(30,1380,'READING THE DIAGRAM',18,True)
text(30,1410,'Solid arrows: bundled payload / functional paths. Purple dashed arrows: timing. Local service fanout is named, not individually routed.',16)
text(30,1440,'8 analog + 1 reference + 22 host + 5 control + 14 supply/return = 50 terminals. No extra LO, loop-filter or analog-monitor pins implied.',16)
text(30,1470,'Multiple identical dies can supply HDMI/DVI data lanes; forwarded-clock interface and cross-die alignment remain board/FPGA obligations.',16)
text(30,1500,'Selected architecture ≠ demonstrated performance. Autonomous noise, full RF quality, pad capacitance and supply/package coupling remain open.',16)
text(30,1530,'Circuit candidate sheets are exploratory detail, not additional required blocks. RF and wired exclusivity saves activity, not fabricated area.',16)
A.append('</g></svg>')
Path(__file__).with_name('transceiver-block-diagram.svg').write_text('\n'.join(A)+'\n')
